#!/usr/bin/env python3
"""Generate saints-of-day-calendar.json with exactly 365 entries (non-leap year)."""

import json
import re
from pathlib import Path

MONTHS = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

SCRIPT_DIR = Path(__file__).resolve().parent
OUTPUT_FILE = SCRIPT_DIR / "saints-of-day-calendar.json"


def slugify(name: str) -> str:
    s = name.lower()
    s = re.sub(r"^st\.?\s+", "st-", s)
    s = re.sub(r"^blessed\s+", "blessed-", s)
    s = re.sub(r"^our lady of ", "our-lady-of-", s)
    s = re.sub(r"[^a-z0-9]+", "-", s)
    return s.strip("-")


def make_entry(month, day, name, patron_of, lifespan, origin, category, facts, title_hook):
    return {
        "month": month,
        "day": day,
        "dateSlug": f"{MONTHS[month - 1]}-{day}",
        "name": name,
        "slug": slugify(name),
        "patronOf": patron_of,
        "lifespan": lifespan,
        "origin": origin,
        "category": category,
        "facts": facts,
        "titleHook": title_hook,
    }


