def build_calendar():
    entries = [make_entry(*row) for row in SAINTS_DATA]
    if len(entries) != 365:
        raise ValueError(f"Expected 365 entries, got {len(entries)}")
    for i, entry in enumerate(entries):
        m, d = entry["month"], entry["day"]
        expected = f"{MONTHS[m - 1]}-{d}"
        if entry["dateSlug"] != expected:
            raise ValueError(f"Bad dateSlug at index {i}: {entry['dateSlug']}")
    return entries


def main():
    entries = build_calendar()
    OUTPUT_FILE.write_text(
        json.dumps(entries, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    size = OUTPUT_FILE.stat().st_size
    print(f"Wrote {len(entries)} entries to {OUTPUT_FILE}")
    print(f"File size: {size} bytes")


if __name__ == "__main__":
    main()
